pub type Temperature = { value: Float64; unit: Str; }

impl Display for Temperature {
  fn to_str(self: &Temperature) -> Str {
    return self.value.to_str() + "°" + self.unit;
  }
}

impl Eq for Temperature {
  fn equals(self: &Temperature, other: &Temperature) -> Bool {
    return self.value == other.value && self.unit == other.unit;
  }
}

fn main() -> Int {
  let t1 = Temperature{ value: 25.0, unit: "C" };
  let t2 = Temperature{ value: 25.0, unit: "C" };
  if t1 == t2 { return 1; }
  return 0;
}
